import{_ as s,c as a,o as n,ag as e}from"./chunks/framework.ymCRTBvy.js";const c=JSON.parse('{"title":"5.4_配置动画插值（Interpolation）效果","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/uikit_animation/5.4_配置动画插值（Interpolation）效果.md","filePath":"uikit/uikit_animation/5.4_配置动画插值（Interpolation）效果.md"}'),t={name:"uikit/uikit_animation/5.4_配置动画插值（Interpolation）效果.md"};function l(h,i,p,k,o,d){return n(),a("div",null,i[0]||(i[0]=[e(`<h1 id="_5-4-配置动画插值-interpolation-效果" tabindex="-1">5.4_配置动画插值（Interpolation）效果 <a class="header-anchor" href="#_5-4-配置动画插值-interpolation-效果" aria-label="Permalink to &quot;5.4_配置动画插值（Interpolation）效果&quot;">​</a></h1><blockquote><p>动画插值，也称为缓动函数，决定了动画在起始值和结束值之间过渡的方式。它控制动画的速度变化，使动画看起来更自然、更流畅。通过调整插值，你可以创建各种各样的动画效果，例如加速、减速、弹跳等。🎉</p></blockquote><h2 id="什么是插值" tabindex="-1">什么是插值？ <a class="header-anchor" href="#什么是插值" aria-label="Permalink to &quot;什么是插值？&quot;">​</a></h2><p>插值本质上是一个数学函数，它将时间（通常是0到1之间的值）映射到动画属性的值。线性插值是最简单的形式，它以恒定的速度改变属性。而非线性插值则可以产生更复杂的效果。想象一下，你正在驾驶一辆汽车🚗。线性插值就像以恒定速度行驶，而非线性插值就像加速或减速。</p><h2 id="uiview-animationoptions-中的插值选项" tabindex="-1">UIView.AnimationOptions 中的插值选项 <a class="header-anchor" href="#uiview-animationoptions-中的插值选项" aria-label="Permalink to &quot;UIView.AnimationOptions 中的插值选项&quot;">​</a></h2><p><code>UIView.AnimationOptions</code> 提供了一些预定义的插值选项，你可以直接使用它们来控制动画的缓动效果。这些选项包括：</p><ul><li><code>.curveLinear</code>：线性插值，动画速度恒定。</li><li><code>.curveEaseIn</code>：动画开始时速度较慢，然后逐渐加速。</li><li><code>.curveEaseOut</code>：动画开始时速度较快，然后逐渐减速。</li><li><code>.curveEaseInOut</code>：动画开始和结束时速度较慢，中间速度较快。</li></ul><p>这些选项可以满足大多数常见的动画需求。例如，<code>.curveEaseOut</code> 经常用于让元素自然地滑入屏幕。</p><h2 id="如何使用插值选项" tabindex="-1">如何使用插值选项 <a class="header-anchor" href="#如何使用插值选项" aria-label="Permalink to &quot;如何使用插值选项&quot;">​</a></h2><p>使用插值选项非常简单。你只需要在调用 <code>UIView.animate(withDuration:delay:options:animations:completion:)</code> 方法时，将相应的选项添加到 <code>options</code> 参数中即可。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UIView.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">animate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">withDuration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">delay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: .curveEaseOut, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">animations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 动画代码</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    view.alpha </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">completion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>在这个例子中，<code>.curveEaseOut</code> 选项会让 <code>view</code> 的透明度在动画开始时快速降低，然后逐渐减速，直到完全消失。</p><h2 id="自定义插值函数" tabindex="-1">自定义插值函数 <a class="header-anchor" href="#自定义插值函数" aria-label="Permalink to &quot;自定义插值函数&quot;">​</a></h2><p>虽然 <code>UIView.AnimationOptions</code> 提供了常用的插值选项，但有时你可能需要更精细的控制。这时，你可以使用 <code>CAMediaTimingFunction</code> 来自定义插值函数。</p><p><code>CAMediaTimingFunction</code> 允许你定义一个贝塞尔曲线，该曲线描述了动画的速度变化。你可以使用 <code>init(controlPoints:_:_:_:)</code> 方法来创建自定义的 <code>CAMediaTimingFunction</code>。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> timingFunction </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CAMediaTimingFunction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">controlPoints</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后，你可以将这个 <code>timingFunction</code> 应用到 <code>CALayer</code> 的 <code>animation</code> 中，从而实现自定义的插值效果。</p><h2 id="示例-弹跳动画" tabindex="-1">示例：弹跳动画 <a class="header-anchor" href="#示例-弹跳动画" aria-label="Permalink to &quot;示例：弹跳动画&quot;">​</a></h2><p>为了更好地理解插值，让我们来看一个弹跳动画的例子。弹跳动画需要一个复杂的插值函数，才能模拟出真实的弹跳效果。你可以使用自定义的 <code>CAMediaTimingFunction</code> 来实现这个效果。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> timingFunction </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CAMediaTimingFunction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">controlPoints</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个 <code>timingFunction</code> 会让动画在到达目标值之前先超过目标值，然后再弹回来，从而产生弹跳的效果。是不是很酷？😎</p><p>通过灵活运用插值，你可以为你的 iOS 应用添加各种各样令人惊艳的动画效果，提升用户体验。记住，动画不仅仅是视觉上的享受，更是提升应用交互性的重要手段。🚀</p>`,22)]))}const E=s(t,[["render",l]]);export{c as __pageData,E as default};
